import{_ as a,c as t,o as s,ag as n}from"./chunks/framework.DCv_I274.js";const u=JSON.parse('{"title":"Full-stack architectures","description":"","frontmatter":{},"headers":[],"relativePath":"fundamentals/full-stack.md","filePath":"fundamentals/full-stack.md","lastUpdated":null}'),r={name:"fundamentals/full-stack.md"};function i(o,e,l,d,p,c){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="full-stack-architectures" tabindex="-1">Full-stack architectures <a class="header-anchor" href="#full-stack-architectures" aria-label="Permalink to &quot;Full-stack architectures&quot;">​</a></h1><p><strong>Full-stack</strong> development means building both halves: the frontend the user sees and the backend that stores and protects the data. The main decision is <strong>where the HTML is produced</strong>.</p><h2 id="_1-server-rendered-pages-mpa-with-blade" tabindex="-1">1. Server-rendered pages (MPA) with Blade <a class="header-anchor" href="#_1-server-rendered-pages-mpa-with-blade" aria-label="Permalink to &quot;1. Server-rendered pages (MPA) with Blade&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Browser ── GET /campuses ──► Laravel ─► Blade template ─► full HTML page</span></span>
<span class="line"><span>Browser ── POST /campuses (form) ──► Laravel ─► redirect ─► GET /campuses</span></span></code></pre></div><ul><li>Laravel renders HTML with <strong>Blade</strong> templates. Every click loads a new page.</li><li>Login uses a <strong>session cookie</strong>; forms are protected with a <strong>CSRF token</strong>.</li><li>Simplest to build and to secure, and good for SEO.</li><li>Less interactive, unless you add some JavaScript (Alpine.js) or Livewire.</li></ul><p><strong>Use it for:</strong> admin panels, internal tools, content sites, small teams.</p><h2 id="_2-single-page-app-spa-json-api" tabindex="-1">2. Single-page app (SPA) + JSON API <a class="header-anchor" href="#_2-single-page-app-spa-json-api" aria-label="Permalink to &quot;2. Single-page app (SPA) + JSON API&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Browser loads the SPA once (Vue / React, built with Vite)</span></span>
<span class="line"><span>SPA ── fetch GET /api/v1/campuses (Bearer token) ──► Laravel API ──► JSON</span></span>
<span class="line"><span>SPA renders the JSON in the browser</span></span></code></pre></div><ul><li>The backend is a pure <strong>API</strong>: no HTML, only JSON.</li><li>The frontend is a separate JavaScript app, often in its own repository and domain.</li><li>The same API can serve a mobile app or other systems.</li><li>More moving parts: CORS, token handling, two deployments.</li></ul><p><strong>Use it for:</strong> highly interactive apps, several clients (web + mobile), separate frontend and backend teams.</p><p><strong>These docs build this kind of backend.</strong> The API is the product, and <a href="/laravel-basics/blade">Blade</a> is covered for the admin or server-rendered parts.</p><h2 id="_3-hybrid-inertia-js-or-livewire" tabindex="-1">3. Hybrid: Inertia.js or Livewire <a class="header-anchor" href="#_3-hybrid-inertia-js-or-livewire" aria-label="Permalink to &quot;3. Hybrid: Inertia.js or Livewire&quot;">​</a></h2><ul><li><strong>Inertia</strong> lets you write Vue/React pages but keep Laravel routing, controllers and session auth; no separate API needed.</li><li><strong>Livewire</strong> makes Blade components interactive with PHP instead of JavaScript.</li></ul><p>Laravel&#39;s starter kits (<code>laravel new</code> → React, Vue or Livewire) set these up for you. They are a good choice for a full-stack app that does <strong>not</strong> need a public API.</p><h2 id="comparison" tabindex="-1">Comparison <a class="header-anchor" href="#comparison" aria-label="Permalink to &quot;Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Blade (MPA)</th><th>SPA + API</th><th>Inertia / Livewire</th></tr></thead><tbody><tr><td>HTML rendered by</td><td>server</td><td>browser</td><td>browser (Inertia) / server (Livewire)</td></tr><tr><td>Auth</td><td>session cookie</td><td>tokens (+ refresh cookie)</td><td>session cookie</td></tr><tr><td>CSRF protection</td><td><code>@csrf</code> token</td><td>origin check on cookie endpoints</td><td>built in</td></tr><tr><td>CORS needed</td><td>no</td><td>yes, if on another domain</td><td>no</td></tr><tr><td>Serves mobile apps too</td><td>no</td><td>yes</td><td>no</td></tr><tr><td>Complexity</td><td>low</td><td>high</td><td>medium</td></tr></tbody></table><h2 id="how-the-layers-stay-reusable" tabindex="-1">How the layers stay reusable <a class="header-anchor" href="#how-the-layers-stay-reusable" aria-label="Permalink to &quot;How the layers stay reusable&quot;">​</a></h2><p>Whatever renders the HTML, keep business logic in <strong>services</strong>. Then a Blade controller and an API controller call the same code:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Blade:  web.php  → CampusPageController    ┐</span></span>
<span class="line"><span>                                            ├─► CampusService ─► Campus model ─► MySQL</span></span>
<span class="line"><span>API:    api.php  → CampusController (JSON) ┘</span></span></code></pre></div><p><a href="/guides/blade-module">A Blade module</a> builds server-rendered pages on top of the same <code>CampusService</code> the API uses.</p><h2 id="where-things-run-in-production" tabindex="-1">Where things run in production <a class="header-anchor" href="#where-things-run-in-production" aria-label="Permalink to &quot;Where things run in production&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                ┌──────────────────────── your server(s) ─────────────────────────┐</span></span>
<span class="line"><span>User ─HTTPS─► Nginx ─┬─► /api/*  → PHP-FPM → Laravel ─► MySQL                      │</span></span>
<span class="line"><span>                     └─► /*      → static SPA files (index.html, JS, CSS)          │</span></span>
<span class="line"><span>                └──────────────────────────────────────────────────────────────────┘</span></span></code></pre></div><p>Putting the SPA and the API under the <strong>same domain</strong> (e.g. <code>app.school.edu</code> and <code>app.school.edu/api</code>) avoids CORS entirely and lets cookies use <code>SameSite=Strict</code>.</p><p>Next: <a href="/fundamentals/security-basics">Security basics</a></p>`,24)])])}const g=a(r,[["render",i]]);export{u as __pageData,g as default};
